                <label for="email">Email address <span aria-hidden="true" class="required-indicator">*</span></label>
                <input 
                    type="email" 
                    id="email" 
                    name="email" 
                    required 
                    autocomplete="email"
                >
                <div id="email-error" class="error-message" hidden>Error: Please enter a valid email address (e.g., name@example.com).</div>
            </div>

            <div class="form-field">
                <label for="phone">Phone number (optional)</label>
                <div id="phone-help" class="help-text">Expected format: +1 (555) 123-4567</div>
                <input 
                    type="tel" 
                    id="phone" 
                    name="phone" 
                    autocomplete="tel"
                    aria-describedby="phone-help"
                >
                <div id="phone-error" class="error-message" hidden>Error: Please enter a valid phone number.</div>
            </div>

            <div class="form-actions">
                <button type="submit">Send message</button>
            </div>

            <div id="status-message" aria-live="polite" class="status-message" hidden></div>
        </form>
