    <script>
document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const nameInput = document.getElementById('name');
    const emailInput = document.getElementById('email');
    const phoneInput = document.getElementById('phone');

    const nameError = document.getElementById('name-error');
    const emailError = document.getElementById('email-error');
    const phoneError = document.getElementById('phone-error');

    const statusMessage = document.getElementById('status-message');

    // Helper to set field invalid state
    function setFieldInvalid(input, errorElement, describedBy) {
        input.setAttribute('aria-invalid', 'true');
        errorElement.removeAttribute('hidden');

        // Add the error ID to aria-describedby
        let currentDescribedBy = input.getAttribute('aria-describedby');
        if (currentDescribedBy) {
            if (!currentDescribedBy.includes(errorElement.id)) {
                input.setAttribute('aria-describedby', `${currentDescribedBy} ${errorElement.id}`);
            }
        } else {
            input.setAttribute('aria-describedby', errorElement.id);
        }
    }

    // Helper to clear field invalid state
    function clearFieldInvalid(input, errorElement) {
        input.removeAttribute('aria-invalid');
        errorElement.setAttribute('hidden', 'true');

        // Remove error ID from aria-describedby
        let currentDescribedBy = input.getAttribute('aria-describedby');
        if (currentDescribedBy) {
            let parts = currentDescribedBy.split(' ').filter(id => id !== errorElement.id);
            if (parts.length > 0) {
                input.setAttribute('aria-describedby', parts.join(' '));
            } else {
                input.removeAttribute('aria-describedby');
            }
        }
    }

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        let isValid = true;
        let firstInvalidField = null;

        // Reset states
        clearFieldInvalid(nameInput, nameError);
        clearFieldInvalid(emailInput, emailError);
        clearFieldInvalid(phoneInput, phoneError);
        statusMessage.setAttribute('hidden', 'true');
        statusMessage.textContent = '';

        // Validate Name
        if (!nameInput.value.trim()) {
            setFieldInvalid(nameInput, nameError);
            isValid = false;
            if (!firstInvalidField) firstInvalidField = nameInput;
        }

        // Validate Email
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailInput.value.trim() || !emailRegex.test(emailInput.value.trim())) {
            setFieldInvalid(emailInput, emailError);
            isValid = false;
            if (!firstInvalidField) firstInvalidField = emailInput;
        }

        // Validate Phone (optional, but if provided should loosely match format)
        // Basic check: just some digits and common characters
        const phoneRegex = /^[\d\s+()-]*$/;
        if (phoneInput.value.trim() && (!phoneRegex.test(phoneInput.value.trim()) || phoneInput.value.trim().length < 7)) {
            setFieldInvalid(phoneInput, phoneError);
            isValid = false;
            if (!firstInvalidField) firstInvalidField = phoneInput;
        }

        if (!isValid) {
            firstInvalidField.focus();
        } else {
            // Success
            statusMessage.textContent = 'Message sent successfully!';
            statusMessage.removeAttribute('hidden');
            form.reset();
        }
    });

    // Clear validation on input
    nameInput.addEventListener('input', () => {
        if (nameInput.hasAttribute('aria-invalid')) {
            clearFieldInvalid(nameInput, nameError);
        }
    });

    emailInput.addEventListener('input', () => {
        if (emailInput.hasAttribute('aria-invalid')) {
            clearFieldInvalid(emailInput, emailError);
        }
    });

    phoneInput.addEventListener('input', () => {
        if (phoneInput.hasAttribute('aria-invalid')) {
            clearFieldInvalid(phoneInput, phoneError);
        }
    });
